  10 // RunsInContainer reports whether one of ids would run from an image: from the
  11 // detection when it holds the tool, else from the configured source, where only
  12 // "image" is a container for certain (auto may find a binary). A tool that
  13 // cannot run runs nowhere, so it never counts.
  14 func RunsInContainer(r *Report, tools config.ScanTools, ids []ToolID) bool {
  15     for _, id := range ids {
  16         if st, ok := r.status(id); ok {
  17             if st.Available && st.Source == ToolSourceContainer {
  18                 return true
  19             }
  20             continue
  21         }
  22         if cfg := tools.Tool(string(id)); cfg != nil && cfg.Source == config.ToolSourceImage {
  23             return true
  24         }
  25     }
  26     return false
  27 }
  28 
  29 // status is the detection of one tool, and whether the report holds it. It is
  30 // safe on a nil report.
  31 func (r *Report) status(id ToolID) (ToolStatus, bool) {
  32     if r == nil {
  33         return ToolStatus{}, false
  34     }
  35     st, ok := r.Tools[id]
  36     return st, ok
  37 }
