  39 // ContainerProxyWarning is the footer text when fwd names a loopback proxy and a
  40 // containerised tool is about to run; "" otherwise. A scanner container has its
  41 // own loopback, so a proxy on this machine's cannot be reached from it. The text
  42 // carries the variable as it was read and the display form of its value, never
  43 // the raw value, so no credential reaches the footer.
  44 func ContainerProxyWarning(fwd netproxy.Forward, containerised bool) string {
  45     if !containerised {
  46         return ""
  47     }
  48     variable, display, ok := fwd.Loopback()
  49     if !ok {
  50         return ""
  51     }
  52     return fmt.Sprintf("%s is %s, on this machine's loopback: scanner containers cannot reach it", variable, display)
  53 }
