   1 package netproxy
   2 
   3 import (
   4     "net/url"
   5     "os"
   6     "slices"
   7     "strings"
   8     "sync"
   9 )
  10 
  11 // ForwardedVariables are the variables a container receives, in this order,
  12 // each name followed by its other casing. ALL_PROXY and FTP_PROXY are not read.
  13 var ForwardedVariables = []string{
  14     "HTTP_PROXY", "http_proxy",
  15     "HTTPS_PROXY", "https_proxy",
  16     "NO_PROXY", "no_proxy",
  17 }
  18 
  19 // redacted stands for a proxy value that could not be parsed, so it has no
  20 // display form.
  21 const redacted = "[redacted]"
  22 
  23 // forwardPair is one variable in both casings, with the value they both carry.
  24 type forwardPair struct {
  25     names [2]string
  26     value string
  27     // read is the name the value was read from, with the case it had.
  28     read string
  29 }
  30 
  31 // Forward is a snapshot of the proxy variables as a child process must receive
  32 // them. It holds raw values, credentials included, and never prints them: String
  33 // and GoString show the display form. A Forward kept in an unexported field is
  34 // walked by fmt, which cannot call String there, so the values sit behind a
  35 // function: fmt prints an address for it, with every verb (a pointer to a struct
  36 // would be followed by %s). The zero value forwards nothing.
  37 type Forward struct {
  38     get func() []forwardPair
  39 }
  40 
  41 // pairs returns the variables held, none for the zero value.
  42 func (f Forward) pairs() []forwardPair {
  43     if f.get == nil {
  44         return nil
  45     }
  46     return f.get()
  47 }
  48 
  49 // containerForward reads the environment once, like http.ProxyFromEnvironment.
  50 var containerForward = sync.OnceValue(func() Forward {
  51     return ForwardFromLookup(os.LookupEnv)
  52 })
  53 
  54 // ContainerForward is the proxy environment of this process, read once.
  55 func ContainerForward() Forward { return containerForward() }
  56 
  57 // ForwardFromLookup reads the variables through lookup. For each of HTTP, HTTPS
  58 // and NO, the first non-empty value of the upper case name then the lower case
  59 // name is given to both names. The value is not validated.
  60 func ForwardFromLookup(lookup func(string) (string, bool)) Forward {
  61     getenv := func(name string) string {
  62         v, _ := lookup(name)
  63         return v
  64     }
  65     var pairs []forwardPair
  66     for i := 0; i < len(ForwardedVariables); i += 2 {
  67         names := [2]string{ForwardedVariables[i], ForwardedVariables[i+1]}
  68         if read, value := firstNonEmpty(names, getenv); read != "" {
  69             pairs = append(pairs, forwardPair{names: names, value: value, read: read})
  70         }
  71     }
  72     if len(pairs) == 0 {
  73         return Forward{}
  74     }
  75     return Forward{get: func() []forwardPair { return pairs }}
  76 }
  77 
  78 // Empty reports whether there is nothing to forward.
  79 func (f Forward) Empty() bool { return len(f.pairs()) == 0 }
  80 
  81 // Names lists the variables to pass, in ForwardedVariables order.
  82 func (f Forward) Names() []string {
  83     var names []string
  84     for _, p := range f.pairs() {
  85         names = append(names, p.names[:]...)
  86     }
  87     return names
  88 }
  89 
  90 // Environ returns base without any of the six forwarded names, followed by
  91 // NAME=value for every name to forward. base is not modified; when there is
  92 // nothing to forward it is returned as is.
  93 func (f Forward) Environ(base []string) []string {
  94     if f.Empty() {
  95         return base
  96     }
  97     env := make([]string, 0, len(base)+len(f.pairs())*2)
  98     for _, kv := range base {
  99         name, _, _ := strings.Cut(kv, "=")
 100         if !slices.Contains(ForwardedVariables, name) {
 101             env = append(env, kv)
 102         }
 103     }
 104     for _, p := range f.pairs() {
 105         for _, name := range p.names {
 106             env = append(env, name+"="+p.value)
 107         }
 108     }
 109     return env
 110 }
 111 
 112 // Loopback reports whether a proxy the container would use is on this machine,
 113 // where it cannot be reached from inside the container. The HTTPS pair is tried
 114 // before the HTTP pair and the first loopback value wins. variable is the name
 115 // that was read and display carries no credential.
 116 func (f Forward) Loopback() (variable, display string, ok bool) {
 117     for _, upper := range []string{"HTTPS_PROXY", "HTTP_PROXY"} {
 118         for _, p := range f.pairs() {
 119             if p.names[0] != upper {
 120                 continue
 121             }
 122             if u, usable := parseProxyValue(p.value); usable && isLoopbackHost(u.Hostname()) {
 123                 return p.read, Display(u), true
 124             }
 125         }
 126     }
 127     return "", "", false
 128 }
 129 
 130 // Redact removes every credential held by f from s: a raw proxy value that
 131 // carries credentials becomes its display form (or [redacted] when it is
 132 // unusable), and its userinfo and its password disappear, as written in the
 133 // value, as Go escapes them and decoded. A value with no credentials is left as
 134 // the tool wrote it, so a diagnostic still names what was dialed. For an
 135 // unusable value holding "@", everything before the last "@" is taken for a
 136 // userinfo. A secret shorter than 4 bytes is only removed in the full value and
 137 // in user:password@, since replacing it anywhere would damage the text; a bare
 138 // user name shorter than 4 bytes is not removed at all.
 139 func (f Forward) Redact(s string) string { return f.Redactor()(s) }
 140 
 141 // Redactor is Redact with the replacements prepared once, for a caller that
 142 // redacts many lines.
 143 func (f Forward) Redactor() func(string) string {
 144     var r redaction
 145     for _, p := range f.pairs() {
 146         if p.names[0] != "NO_PROXY" {
 147             r.addValue(p.value)
 148         }
 149     }
 150     return r.replacer()
 151 }
 152 
 153 // redaction collects what Redact removes. strings.Replacer tries its arguments
 154 // in order at each position, so replacer lists the longest kinds first.
 155 type redaction struct {
 156     values    [][2]string // raw value and what stands for it
 157     userinfos []string    // removed together with their "@"
 158     secrets   []string    // replaced wherever they appear
 159 }
 160 
 161 // addValue records one raw proxy value and the credentials it holds. A value
 162 // with none is not recorded: replacing it by its display form would only distort
 163 // the text around it.
 164 func (r *redaction) addValue(value string) {
 165     display := redacted
 166     u, usable := parseProxyValue(value)
 167     hasCredentials := !usable && strings.Contains(value, "@")
 168     if usable {
 169         display = Display(u)
 170         if u.User != nil {
 171             hasCredentials = true
 172             r.addUserinfo(u.User.String())
 173         }
 174     }
 175     if !hasCredentials {
 176         return
 177     }
 178     r.values = append(r.values, [2]string{value, display})
 179     rest := value[len(explicitScheme.FindString(value)):]
 180     if usable {
 181         // The authority ends at the first "/", "?" or "#".
 182         if end := strings.IndexAny(rest, "/?#"); end >= 0 {
 183             rest = rest[:end]
 184         }
 185     }
 186     // Written out, whatever the escaping: up to the last "@".
 187     if at := strings.LastIndex(rest, "@"); at >= 0 {
 188         r.addUserinfo(rest[:at])
 189     }
 190 }
 191 
 192 // addUserinfo records a userinfo as written, user[:password], and its decoded
 193 // form. The secret is the password, or the user name when the password is
 194 // absent or empty.
 195 func (r *redaction) addUserinfo(info string) {
 196     user, password, _ := strings.Cut(info, ":")
 197     secret := password
 198     if secret == "" {
 199         secret = user
 200     }
 201     for _, v := range unescapedToo(info) {
 202         // A bare short name would match the local part of an address.
 203         if v != "" && (strings.Contains(v, ":") || len(v) >= 4) {
 204             r.userinfos = append(r.userinfos, v)
 205         }
 206     }
 207     for _, v := range unescapedToo(secret) {
 208         if len(v) >= 4 {
 209             r.secrets = append(r.secrets, v)
 210         }
 211     }
 212 }
 213 
 214 // unescapedToo returns s and, when it differs and decodes, its percent-decoded form.
 215 func unescapedToo(s string) []string {
 216     if d, err := url.PathUnescape(s); err == nil && d != s {
 217         return []string{s, d}
 218     }
 219     return []string{s}
 220 }
 221 
 222 // replacer builds the replacements once and returns the function applying them.
 223 func (r *redaction) replacer() func(string) string {
 224     var olds []string
 225     byLength := func(a, b string) int { return len(b) - len(a) }
 226     slices.SortStableFunc(r.values, func(a, b [2]string) int { return byLength(a[0], b[0]) })
 227     for _, v := range r.values {
 228         olds = append(olds, v[0], v[1])
 229     }
 230     slices.SortStableFunc(r.userinfos, byLength)
 231     for _, info := range slices.Compact(r.userinfos) {
 232         olds = append(olds, info+"@", "")
 233     }
 234     slices.SortStableFunc(r.secrets, byLength)
 235     for _, secret := range slices.Compact(r.secrets) {
 236         olds = append(olds, secret, redacted)
 237     }
 238     if len(olds) == 0 {
 239         return func(s string) string { return s }
 240     }
 241     return strings.NewReplacer(olds...).Replace
 242 }
 243 
 244 // String shows the variables with the proxies in display form, never raw. A
 245 // NO_PROXY value with a non-printable character is not shown, since it ends up
 246 // on a terminal.
 247 func (f Forward) String() string {
 248     if f.Empty() {
 249         return "no proxy variables"
 250     }
 251     parts := make([]string, 0, len(f.pairs()))
 252     for _, p := range f.pairs() {
 253         shown := redacted
 254         if p.names[0] == "NO_PROXY" {
 255             if isPrintable(p.value) {
 256                 shown = p.value
 257             }
 258         } else if u, ok := parseProxyValue(p.value); ok {
 259             shown = Display(u)
 260         }
 261         parts = append(parts, p.names[0]+"="+shown)
 262     }
 263     return strings.Join(parts, " ")
 264 }
 265 
 266 // GoString is String, so %#v shows no raw value either.
 267 func (f Forward) GoString() string { return f.String() }

